{
  "vulnerabilidade_identificada": "Acesso não autorizado a cestas de outros usuários ao adicionar itens (IDOR/Broken Access Control).",
  "causa_da_vulnerabilidade": "A validação compara o BasketId informado com a cesta do usuário autenticado, mas, quando há divergência, apenas envia uma resposta 401 e continua a execução. Assim, o item ainda pode ser salvo na cesta indicada pelo cliente.",
  "estrategia_de_correcao": "Encerrar o fluxo imediatamente após enviar a resposta 401, impedindo a criação do item quando o BasketId não pertence ao usuário autenticado.",
  "edicoes": [
    {
      "arquivo": "routes/basketItems.ts",
      "trecho_original": "    if (user && basketIds[0] && basketIds[0] !== 'undefined' && Number(user.bid) != Number(basketIds[0])) { // eslint-disable-line eqeqeq\n      res.status(401).send('{\\'error\\' : \\'Invalid BasketId\\'}')\n    } else {",
      "trecho_corrigido": "    if (user && basketIds[0] && basketIds[0] !== 'undefined' && Number(user.bid) != Number(basketIds[0])) { // eslint-disable-line eqeqeq\n      return res.status(401).send('{\\'error\\' : \\'Invalid BasketId\\'}')\n    } else {"
    }
  ],
  "justificativa_tecnica": "O retorno encerra o handler após a resposta de erro, evitando que a execução alcance BasketItemModel.build e save. A validação existente e o comportamento para requisições autorizadas permanecem inalterados.",
  "limitacoes_da_correcao": "A correção impede a gravação após a divergência detectada, mas não altera a validação existente para requisições sem usuário autenticado nem outros fluxos de autorização."
}
